	t.Parallel()
	snap := localMetaSnapshot(t, "aaa111aaa111")
	checkpoints := localMetaCheckpoints("aaa111aaa111")
	local, _ := newLocalCheckpointMetadata(snap, checkpoints)
	if local == nil {
		t.Fatal("shortcut declined a covering snapshot")
