// routed, and declaring which sessions the checkpoint has.
func routedEntry(id string, sessionIDs ...string) checkpointListEntry {
	return checkpointListEntry{
		CheckpointID: id,
		IsLogsOnly:   true,
		RoutedOrigin: true,
		SessionIDs:   sessionIDs,
		SessionCount: len(sessionIDs),
	}
}

