	for _, entry := range discovered {
		if entry.CheckpointID != "" {
			discoveredIDs[entry.CheckpointID] = struct{}{}
		}
	}

	outside := 0
	for _, session := range snapshot.Selected {
		if _, ok := discoveredIDs[session.CheckpointID]; !ok {
			outside++
		}
	}
